/** Combine Vue class bindings with the shared utility recipes. */
export function ui(...values: ClassValue[]): string {
  const names: string[] = []
  function collect(value: ClassValue) {
    if (!value) return
    if (typeof value === 'string' || typeof value === 'number') names.push(...String(value).split(/\s+/).filter(Boolean))
    else if (Array.isArray(value)) value.forEach(collect)
    else if (typeof value === 'object') for (const [name, enabled] of Object.entries(value)) if (enabled) collect(name)
  }
  values.forEach(collect)
  const markers = names.filter(name => !name.startsWith('$') && recipes[name])
  const utilities = twMerge(names.map(name => recipes[name] ?? (name.startsWith('$') ? '' : name)).join(' '))
  return [...new Set([...markers, ...utilities.split(/\s+/).filter(Boolean)])].join(' ')
}
